function modelLogo(m){return `<img class="provider-logo" src="assets/logos/${logoNames[m.id]}.svg" alt="" width="26" height="26">`;}
function syncViewportLock(){const intro=!$('#onboarding').classList.contains('hidden');const workspace=!$('#workspace').classList.contains('hidden');const replied=conversations.find(c=>c.id===activeChat)?.messages.some(m=>m.role==='assistant');document.body.classList.toggle('intro-open',intro);document.body.classList.toggle('workspace-unanswered',!intro&&workspace&&!replied);}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function persist(){if(!saveChats)return;try{localStorage.setItem(storageKey,JSON.stringify({version:2,plan,conversations}));}catch{toast('Your browser could not save these chats. They remain in this tab.');}}
function loadSaved(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'null');if(data?.version!==2||!Array.isArray(data.conversations))return;conversations=data.conversations.filter(c=>typeof c.id==='string'&&typeof c.title==='string'&&Array.isArray(c.messages)).slice(0,50).map(c=>({...c,messages:c.messages.filter(m=>['user','assistant','notice'].includes(m.role)&&typeof m.text==='string'&&(!m.route||models.some(x=>x.id===m.route.winner?.id))).slice(0,100)}));plan=plans.some(p=>p.name===data.plan)?data.plan:'Free';saveChats=true;$('#save-setting').checked=true;}catch{}}
function plansHTML(){return `<div class="plan-switcher" role="tablist" aria-label="Choose a plan">${plans.map((p,i)=>`<button type="button" role="tab" aria-selected="${i===0}" class="plan-tab ${i===0?'active':''}" data-plan-tab="${i}"> ${p.name}</button>`).join('')}</div><div class="plans-grid">${plans.map((p,i)=>`<article class="plan ${i===0?'mobile-selected':''}" data-plan-card="${i}" aria-label="${p.name} plan"><p class="plan-number">0${i+1} / YOUR PACE</p>${i===1?'<span class="popular-label">Most popular</span>':''}<h2>${p.name}</h2><p class="plan-price">${p.price}${i?'<small> / month</small>':''}</p><p class="plan-usd">${p.usd}</p><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="${i===1?'primary-button':'secondary-button'}" data-plan="${p.name}">${p.button}</button></article>`).join('')}</div>`;}
function bindPlans(container){
 $$(`${container} [data-plan-tab]`).forEach(tab=>tab.onclick=()=>{const index=tab.dataset.planTab;$$(`${container} [data-plan-tab]`).forEach(b=>{b.classList.toggle('active',b.dataset.planTab===index);b.setAttribute('aria-selected',String(b.dataset.planTab===index));});$$(`${container} [data-plan-card]`).forEach(card=>card.classList.toggle('mobile-selected',card.dataset.planCard===index));});
$$(`${container} [data-plan]`).forEach(b=>b.addEventListener('click',()=>{plan=b.dataset.plan;$('#plans-dialog').close();$('#plan-label').textContent=plan+' preview';$('#account-plan').textContent=plan+' tier preview';persist();$('#onboarding').classList.add('hidden');$('#app').classList.remove('hidden');showView('workspace');$('#prompt').focus();toast(plan+' preview selected. No payment or subscription created.');}));}
function renderIntro(step){introStep=step;document.body.classList.add('intro-open');document.body.classList.remove('workspace-unanswered');$('#onboarding').classList.remove('hidden');$('#app').classList.add('hidden');const stage=$('#intro-stage');
 if(step===0)stage.innerHTML='<div class="intro-copy"><div class="intro-symbol" aria-hidden="true">z<sup>°</sup></div><p class="eyebrow">A LITTLE LESS EFFORT. A LOT MORE POSSIBILITY.</p><h1>Welcome to<br><em>ZeroPrompt.</em></h1><p>Your place to use AI without perfecting the prompt. Just tell us what you want to get done.</p><button class="primary-button" id="intro-next">Continue <span aria-hidden="true">↗</span></button></div>';
 if(step===1)stage.innerHTML='<div class="intro-copy"><div class="intro-symbol" aria-hidden="true">✳</div><p class="eyebrow">BRING THE IDEA. WE’LL FIND THE ROUTE.</p><h1>One space.<br><em>Different kinds of brilliant.</em></h1><p>ZeroPrompt brings multiple AI models together and helps route your request to a suitable one. Describe the outcome in your own words.</p><div class="intro-steps"><span>Write naturally</span><span>Let Auto choose</span><span>Understand the route</span></div><button class="primary-button" id="intro-next">Continue <span aria-hidden="true">↗</span></button></div>';
 if(step===2){stage.innerHTML='<div class="plan-intro"><div class="plan-heading"><p class="eyebrow">A LITTLE MORE POSSIBILITY</p><h1>Find your <em>pace.</em></h1><p>Start with Free. Explore what a little more room could look like.</p></div>'+plansHTML()+'<button class="text-button plan-back" id="intro-back">← Back</button></div>';bindPlans('#intro-stage');$('#intro-back').onclick=()=>renderIntro(1);}
 $('#intro-progress').innerHTML=[0,1,2].map(i=>`<button class="${i===step?'active':''}" aria-label="Introduction step ${i+1}${i===step?', current':''}" ${i===step?'aria-current="step"':''} data-step="${i}"></button>`).join('');$$('[data-step]').forEach(b=>b.onclick=()=>renderIntro(Number(b.dataset.step)));$('#skip-intro').classList.toggle('hidden',step===2);if($('#intro-next'))$('#intro-next').onclick=()=>renderIntro(step+1);window.scrollTo({top:0});}
function openPlans(){$('#modal-plans').innerHTML=plansHTML();bindPlans('#modal-plans');$('#plans-dialog').showModal();}
function closeSidebar(){closeChatMenu();$('#sidebar').classList.remove('open');$('#sidebar-scrim').classList.add('hidden');$('#menu-button').setAttribute('aria-expanded','false');}
function showView(id){if(!['workspace','library','benchmark','about','settings','account'].includes(id))return;$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===id);if(b.dataset.view===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#view-label').textContent={workspace:'Your workspace',library:'Model library',benchmark:'Model comparison',about:'How it works',settings:'Settings',account:'Your account'}[id];closeSidebar();syncViewportLock();window.scrollTo({top:0,behavior:'smooth'});}
function classify(prompt){if(/\b(image|poster|illustration|visual|picture|photo|logo)\b/i.test(prompt))return 3;if(/\b(legal|law|lawyer|contract|jurisdiction|liability)\b/i.test(prompt))return 6;if(/\b(finance|financial|saving|savings|interest|baht|tax|investment)\b/i.test(prompt))return 4;if(/\b(research|study|sources|evidence|literature)\b/i.test(prompt))return 5;if(/\b(code|python|javascript|function|sql|debug|algorithm)\b/i.test(prompt))return 2;if(/\b(decide|decision|compare|reason|whether|versus|in-house)\b/i.test(prompt))return 1;return 0;}
function evaluate(prompt,options={}){const task=options.task??classify(prompt),priority=options.priority??$('[name=priority]:checked').value,budget=options.budget??Number($('#budget').value)/1000,region=options.region??$('#region-setting').value,manual=options.manual??selectedModel;const inputTokens=Math.ceil(prompt.length/3.6)+180,outputTokens=[260,450,350,320,320,520,430][task];const weights={quality:[.92,.04,.04],balanced:[.65,.23,.12],economy:[.28,.65,.07]}[priority];const rows=models.map(m=>{const cost=(inputTokens*m.input+outputTokens*m.output)/1e6,reason=!enabled.has(m.id)?'Disabled by you':region!=='all'&&m.origin!==region?'Outside provider preference':cost>budget?'Above text-cost budget':'';return{...m,cost,taskFit:m.fit[task],score:m.fit[task]*weights[0]+100*(1-Math.min(cost/.025,1))*weights[1]+100*(1-m.time/25)*weights[2],eligible:!reason,reason};});const eligible=rows.filter(m=>m.eligible).sort((a,b)=>b.score-a.score);const winner=manual==='auto'?eligible[0]:eligible.find(m=>m.id===manual);return{task,priority,budget,region,manual,inputTokens,outputTokens,rows:rows.sort((a,b)=>Number(b.eligible)-Number(a.eligible)||b.score-a.score),winner,eligibleCount:eligible.length};}
function renderChats(){closeChatMenu();$('#chat-total').textContent=conversations.length;$('#chat-list').innerHTML=conversations.length?conversations.map(c=>`<div class="chat-row ${c.id===activeChat?'active':''}"><button class="chat-item" data-chat="${esc(c.id)}" title="${esc(c.title)}">${esc(c.title)}</button><button class="chat-menu-trigger" data-chat-menu="${esc(c.id)}" aria-label="Options for ${esc(c.title)}" aria-haspopup="menu" aria-expanded="false">⋯</button></div>`).join(''):'<p class="chat-empty">A fresh page.<br>Your conversations will live here.</p>';$$('[data-chat]').forEach(b=>b.onclick=()=>{if(running)cancelRun();activeChat=b.dataset.chat;showView('workspace');renderMessages();renderChats();});$$('[data-chat-menu]').forEach(b=>b.onclick=e=>{e.stopPropagation();openChatMenu(b);});}
function closeChatMenu(){const menu=$('#chat-menu');if(menu)menu.hidden=true;chatMenuAnchor?.setAttribute('aria-expanded','false');chatMenuAnchor=null;}
function openChatMenu(button){const same=chatMenuAnchor===button&&!$('#chat-menu').hidden;closeChatMenu();if(same)return;chatActionId=button.dataset.chatMenu;chatMenuAnchor=button;button.setAttribute('aria-expanded','true');const menu=$('#chat-menu');menu.hidden=false;const r=button.getBoundingClientRect();menu.style.left=Math.max(10,Math.min(r.right-160,innerWidth-175))+'px';menu.style.top=Math.min(r.bottom+5,innerHeight-100)+'px';menu.querySelector('button').focus();}
function codingExplanation(){return 'The function checks each item against the result list and appends it only if it has not appeared before. This preserves the original order and supports unhashable items. The assertions test duplicate removal and an empty input. Worst-case time is O(n²), with O(n) extra space.';}
function responseHTML(m){if(m.route.task===3)return '<img class="meme-result" src="assets/confusion-matrix.png" alt="Confusion matrix meme: true positive, false positive, false negative, and true negative, illustrated with pregnancy test examples." width="1536" height="1024">';if(m.route.task===2){const parts=m.text.split('\n\nExplanation\n');return '<pre><code>'+esc(parts[0])+'</code></pre><p class="code-explanation">'+esc(parts[1]||codingExplanation())+'</p>';}return esc(m.text);}
function renderMessages(){const c=conversations.find(c=>c.id===activeChat);$('.workspace-inner').classList.toggle('has-messages',!!c?.messages.length);$('.workspace-inner').classList.toggle('has-reply',!!c?.messages.some(m=>m.role==='assistant'));syncViewportLock();$('#messages').innerHTML=(c?.messages||[]).map(m=>{if(m.role==='user')return`<article class="message user">${esc(m.text)}</article>`;if(m.role==='notice')return`<p class="message micro">${esc(m.text)}</p>`;const model=models.find(x=>x.id===m.route.winner.id);return`<article class="message assistant" data-message="${esc(m.id)}"><div class="response-byline">${modelLogo(model)}<span>${esc(model.name)}</span><small>${m.route.task===3?'DEMO IMAGE':'PREPARED DEMO RESPONSE'}</small></div><div class="response-body ${m.route.task===3?'image-response':''}">${responseHTML(m)}</div>${m.route.task===3?'':`<span class="sample-label">Prepared ${esc(tasks[m.route.task].toLowerCase())} sample, not a generated answer to your message.</span>`}<div class="response-actions"><button class="explain-route" data-route="${esc(m.id)}">Explain the route ↗</button>${m.route.task===3?'':`<button data-copy="${esc(m.id)}">Copy</button>`}<button data-download="${esc(m.id)}">${m.route.task===3?'Save image':'Save .txt'}</button></div></article>`;}).join('');$$('[data-route]').forEach(b=>b.onclick=()=>openRoute(b.dataset.route,b));$$('[data-copy]').forEach(b=>b.onclick=()=>copyResponse(b.dataset.copy));$$('[data-download]').forEach(b=>b.onclick=()=>downloadResponse(b.dataset.download));}
function findMessage(id){return conversations.flatMap(c=>c.messages).find(m=>m.id===id);}
async function copyResponse(id){const m=findMessage(id);if(!m)return;try{await navigator.clipboard.writeText(m.text);toast('Response copied.');}catch{toast('Clipboard unavailable. Select the response text to copy it.');}}
function downloadResponse(id){const m=findMessage(id);if(!m)return;if(m.route.task===3){const a=document.createElement('a');a.href='assets/confusion-matrix.png';a.download='ZeroPrompt-Confusion-Matrix.png';a.click();return;}const url=URL.createObjectURL(new Blob(['ZeroPrompt prepared demo response\nModel: '+m.route.winner.name+'\n\n'+m.text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ZeroPrompt-demo-response.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function newChat(){if(running)cancelRun();activeChat=null;$('#prompt').value='';syncPlaceholder();renderMessages();renderChats();showView('workspace');$('#prompt').focus();}
function cancelRun(){if(!running)return;clearTimeout(running.timer);const c=conversations.find(c=>c.id===running.chat);c?.messages.push({id:uid(),role:'notice',text:'Routing cancelled. Your message is still in this conversation.'});running=null;$('#send-button').classList.remove('running');$('#send-button').innerHTML='<span aria-hidden="true">↑</span>';$('#send-button').setAttribute('aria-label','Send message');renderMessages();persist();}
function sendMessage(event){event.preventDefault();if(running){cancelRun();return;}const prompt=$('#prompt').value.trim();if(!prompt){$('#form-error').textContent='Describe an outcome or choose a demo prompt to begin.';$('#prompt').focus();return;}const r=evaluate(prompt);if(!r.winner){$('#form-error').textContent=r.manual!=='auto'?'Your chosen model is disabled, outside your provider preference, or above the text-cost budget. Change your selection or constraints.':'No models meet these limits. Enable a model or adjust your budget and provider preference.';return;}$('#form-error').textContent='';if(!activeChat){activeChat=uid();conversations.unshift({id:activeChat,title:prompt.slice(0,55),messages:[]});}const c=conversations.find(c=>c.id===activeChat);c.messages.push({id:uid(),role:'user',text:prompt});$('#prompt').value='';syncPlaceholder();renderMessages();renderChats();$('#messages').insertAdjacentHTML('beforeend','<p class="pending" role="status">Choosing a route</p>');$('#send-button').classList.add('running');$('#send-button').innerHTML='■';$('#send-button').setAttribute('aria-label','Stop routing');persist();const token={chat:activeChat};running=token;token.timer=setTimeout(()=>{if(running!==token)return;c.messages.push({id:uid(),role:'assistant',text:responses[r.task],route:r});running=null;$('#send-button').classList.remove('running');$('#send-button').innerHTML='<span aria-hidden="true">↑</span>';$('#send-button').setAttribute('aria-label','Send message');renderMessages();persist();const last=$('#messages .assistant:last-child');last?.scrollIntoView({behavior:document.body.classList.contains('still')?'auto':'smooth',block:'start'});},document.body.classList.contains('still')?100:1200);}
function openRoute(id,button){const m=findMessage(id);if(!m?.route)return;const r=m.route,w=r.winner;routeReturnFocus=button;$('#route-content').innerHTML=`<p class="selected-for">SELECTED FOR ${esc(tasks[r.task].toUpperCase())}</p><h2 id="route-title">${esc(w.name)}</h2><p class="route-provider">${esc(w.provider)} / ${w.origin==='us'?'U.S.':'China'}</p><p class="route-reason">${r.manual==='auto'?'Auto selected the highest weighted demo score among models meeting your constraints.':'You selected this model manually. It met your current constraints.'} ${esc(w.tag)} is its illustrative profile.</p><dl class="route-stats"><div><dt>Estimated cost</dt><dd>${money(w.cost)}</dd></div><div><dt>Estimated tokens</dt><dd>${(r.inputTokens+r.outputTokens).toLocaleString()}</dd></div><div><dt>Modeled time</dt><dd>~${w.time}<small> seconds</small></dd></div><div><dt>Demo task fit</dt><dd>${w.taskFit}<small> / 100</small></dd></div></dl><p class="route-constraints">${r.inputTokens} estimated input + ${r.outputTokens} estimated output tokens<br>${esc(priorityNames[r.priority])} · Budget $${r.budget.toFixed(3)}<br>${r.eligibleCount} eligible models · ${r.manual==='auto'?'Automatic route':'Manual selection'}</p><h3>The alternatives</h3>${r.rows.filter(x=>x.id!==w.id).map(x=>`<div class="route-alternative"><span>${esc(x.name)}<small>${esc(x.reason||'Eligible')} · ${money(x.cost)}</small></span><span>${x.taskFit}/100</span></div>`).join('')}<p class="data-disclosure">No tokens were consumed by a live model. Cost, time, token counts, and fit are simulated estimates. The image example displays a provided demo asset. It does not call an image-generation API.</p>`;$('#route-drawer').hidden=false;$('#route-scrim').classList.remove('hidden');$('#app').inert=true;document.body.style.overflow='hidden';$('#close-route').focus();}
function closeRoute(){$('#route-drawer').hidden=true;$('#route-scrim').classList.add('hidden');$('#app').inert=false;document.body.style.overflow='';routeReturnFocus?.focus();}
function renderPicker(){const query=$('#picker-search').value.toLowerCase();const visible=models.filter(m=>(m.name+' '+m.provider).toLowerCase().includes(query));$('#model-options').innerHTML=`<button class="model-option ${selectedModel==='auto'?'selected':''}" data-pick="auto"><span aria-hidden="true">✳</span><span>Auto<small>Let the task and your priorities guide the choice</small></span>${selectedModel==='auto'?'<span class="selection-dot" aria-hidden="true"></span>':''}</button>`+visible.map(m=>`<button class="model-option ${selectedModel===m.id?'selected':''}" data-pick="${m.id}" ${!enabled.has(m.id)?'disabled':''}>${modelLogo(m)}<span>${esc(m.name)}<small>${esc(m.provider)}${!enabled.has(m.id)?' · Disabled in library':''}</small></span>${selectedModel===m.id?'<span class="selection-dot" aria-hidden="true"></span>':''}</button>`).join('')+(!visible.length?'<p class="micro">No models match that search.</p>':'');$$('[data-pick]').forEach(b=>b.onclick=()=>{selectedModel=b.dataset.pick;$('#model-label').textContent=selectedModel==='auto'?'Auto':models.find(m=>m.id===selectedModel).name;$('#model-dialog').close();$('#model-button').focus();});}
function renderLibrary(){const q=$('#model-search').value.toLowerCase(),filtered=models.filter(m=>(m.name+' '+m.provider).toLowerCase().includes(q));$('#model-library').innerHTML=filtered.map(m=>`<article class="library-item"><header><span class="eyebrow">${esc(m.provider)} / ${m.origin==='us'?'U.S.':'CHINA'}</span><label><span class="sr-only">Include ${esc(m.name)} in Auto routing</span><input type="checkbox" data-enable="${m.id}" ${enabled.has(m.id)?'checked':''}></label></header><h2 class="model-heading">${modelLogo(m)}${esc(m.name)}</h2><p>${esc(m.tag)}</p><div class="library-meta"><span>Demo input <strong>$${m.input.toFixed(2)}</strong></span><span>Demo output <strong>$${m.output.toFixed(2)}</strong></span><span>per 1M tokens</span></div></article>`).join('')||'<p class="micro">No models match that search.</p>';$$('[data-enable]').forEach(input=>input.onchange=()=>{input.checked?enabled.add(input.dataset.enable):enabled.delete(input.dataset.enable);if(!enabled.has(selectedModel)){selectedModel='auto';$('#model-label').textContent='Auto';}toast(enabled.size+' of 12 models enabled for Auto.');});}
const benchmarkCategories=['Coding','Agentic Tasks','Data Analysis','Research','Design','Cost per Task','Context Window','Model time'];
const subcategories={'Agentic Tasks':['Overview','Finance & Compliance Apps','Operations & Commerce Apps','Long-Run Operations','Systems Engineering','Performance Optimisation'],Coding:['Overview','LLM API Integration','Agent Loop','Cloud Infrastructure','Product & UX','Memory & Tools'],Research:['Overview','Regulatory & Compliance','Legal','Tax & Finance','Strategy','Science & Evidence'],Design:['Overview','Documents (DOCX)','PDF','Presentation (PPT)']};
let benchmarkCategory='Coding',benchmarkSubtask='Overview';
const agenticProfiles={opus:[91,88,89,88,84],fable:[93,90,96,89,86],astra:[97,96,95,96,94],sol:[91,92,90,98,96],gemini:[86,90,88,87,85],qwen:[96,90,87,90,91],kimi:[93,94,97,88,85],muse:[81,86,80,79,78],deepseek:[88,86,84,94,97],grok:[87,93,86,87,85],glm:[90,92,91,93,90],mimo:[88,88,86,91,93]};
function comparisonScore(m,i,task){if(benchmarkCategory==='Agentic Tasks'){const values=agenticProfiles[m.id];const index=subcategories['Agentic Tasks'].indexOf(benchmarkSubtask)-1;return index<0?Math.round(values.reduce((a,b)=>a+b,0)/values.length):values[index];}return Math.max(0,Math.min(100,m.fit[task]+(benchmarkSubtask==='Overview'?0:((i*3+benchmarkSubtask.length)%7)-3)));}
function benchmarkTask(){if(benchmarkCategory==='Data Analysis')return 4;if(benchmarkCategory==='Agentic Tasks')return 2;if(benchmarkCategory==='Coding')return benchmarkSubtask==='Product & UX'?3:2;if(benchmarkCategory==='Research')return({'Legal':6,'Tax & Finance':4,'Strategy':1})[benchmarkSubtask]??5;return benchmarkSubtask==='Overview'?3:0;}
function renderBenchmark(){const labels=['Model',benchmarkCategory==='Agentic Tasks'?'Demo agentic fit':'Demo task fit','Est. text cost','Modeled time'];$('#benchmark-tabs').innerHTML=benchmarkCategories.map((c,i)=>`<button role="tab" id="benchmark-tab-${i}" aria-controls="benchmark-panel" aria-selected="${c===benchmarkCategory}" tabindex="${c===benchmarkCategory?0:-1}" data-category="${esc(c)}">${c}</button>`).join('');$('#benchmark-panel').setAttribute('aria-labelledby','benchmark-tab-'+benchmarkCategories.indexOf(benchmarkCategory));$('#benchmark-subtasks').innerHTML=(subcategories[benchmarkCategory]||[]).map(s=>`<button data-subtask="${esc(s)}" class="${s===benchmarkSubtask?'active':''}" aria-pressed="${s===benchmarkSubtask}">${esc(s)}</button>`).join('');const task=benchmarkTask();let rows=models.map((m,i)=>({...m,cost:(1000*m.input+500*m.output)/1e6,score:comparisonScore(m,i,task)}));if(benchmarkCategory==='Cost per Task')rows.sort((a,b)=>a.cost-b.cost);else if(benchmarkCategory==='Context Window')rows.sort((a,b)=>b.context-a.context);else if(benchmarkCategory==='Model time')rows.sort((a,b)=>a.time-b.time);else rows.sort((a,b)=>b.score-a.score);if(benchmarkCategory==='Context Window')labels[1]='Demo context capacity';$('#benchmark-head').innerHTML='<tr>'+labels.map(x=>`<th scope="col">${x}</th>`).join('')+'</tr>';$('#benchmark-body').innerHTML=rows.map((m,i)=>`<tr><th scope="row"><span class="rank">${String(i+1).padStart(2,'0')}</span>${esc(m.name)}<small>${esc(m.provider)}</small></th><td>${benchmarkCategory==='Context Window'?m.context.toLocaleString()+'k demo tokens':`<span class="score-track"><i style="width:${m.score}%"></i></span>${m.score}/100`}</td><td>${money(m.cost)}</td><td>~${m.time}s</td></tr>`).join('');$$('[data-category]').forEach(b=>b.onclick=()=>{benchmarkCategory=b.dataset.category;benchmarkSubtask='Overview';renderBenchmark();$('#benchmark-tab-'+benchmarkCategories.indexOf(benchmarkCategory)).focus();});$$('[data-subtask]').forEach(b=>b.onclick=()=>{benchmarkSubtask=b.dataset.subtask;renderBenchmark();$('[data-subtask="'+CSS.escape(benchmarkSubtask)+'"]').focus();});}
function syncPlaceholder(){$('#animated-placeholder').classList.toggle('hidden',!!$('#prompt').value);$('#form-error').textContent='';}
let placeholderIndex=0,placeholderTimer;const placeholders=['What’s the vibe?','How can I help you today?','Ask away.','A little idea. A big possibility.','What would you like to get done?'];
setInterval(()=>{if($('#prompt').value||$('#onboarding').classList.contains('hidden')===false||document.body.classList.contains('still')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;$('#animated-placeholder').classList.add('fade');clearTimeout(placeholderTimer);placeholderTimer=setTimeout(()=>{$('#animated-placeholder').textContent=placeholders[++placeholderIndex%placeholders.length];$('#animated-placeholder').classList.remove('fade');},300);},3500);
$('#demo-prompts').innerHTML=demos.map((d,i)=>`<button class="demo-prompt" data-demo="${i}"><span aria-hidden="true">${d.icon}</span>${d.label}</button>`).join('');$$('[data-demo]').forEach(b=>b.onclick=()=>{const d=demos[Number(b.dataset.demo)];selectedModel='auto';enabled=new Set(models.map(m=>m.id));$('#model-label').textContent='Auto';$('[name=priority][value=quality]').checked=true;$('#budget').value=50;$('#budget-output').textContent='$0.050';$('#region-setting').value='all';renderLibrary();$('#prompt').value=d.prompt;syncPlaceholder();$('#prompt').focus();toast('Demo preset: Auto, best quality, all models, $0.050 text budget.');});
$('#composer-form').addEventListener('submit',sendMessage);$('#prompt').addEventListener('input',syncPlaceholder);$('#prompt').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#composer-form').requestSubmit();}});$('#advanced-button').onclick=openAdvanced;$('#reset-priorities').onclick=()=>{$('[name=priority][value=quality]').checked=true;$('#budget').value=50;$('#budget-output').textContent='$0.050';};$('#budget').oninput=()=>$('#budget-output').textContent='$'+(Number($('#budget').value)/1000).toFixed(3);$('#model-button').onclick=()=>{$('#picker-search').value='';renderPicker();$('#model-dialog').showModal();};$('#picker-search').oninput=renderPicker;$('#model-search').oninput=renderLibrary;$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('.brand').forEach(b=>b.onclick=e=>{e.preventDefault();if(!$('#app').classList.contains('hidden'))showView('workspace');else renderIntro(0);});$('#new-chat').onclick=newChat;$('#plans-button').onclick=openPlans;$('#account-plans').onclick=openPlans;$('#skip-intro').onclick=()=>renderIntro(2);$('#replay-intro').onclick=()=>{if(running)cancelRun();renderIntro(0);};$('#menu-button').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#sidebar-scrim').classList.toggle('hidden',!open);$('#menu-button').setAttribute('aria-expanded',open);};$('#sidebar-scrim').onclick=closeSidebar;$('#close-route').onclick=closeRoute;$('#route-scrim').onclick=closeRoute;$$('[data-close-dialog]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));$('#motion-setting').onchange=e=>document.body.classList.toggle('still',!e.target.checked);$('#save-setting').onchange=e=>{saveChats=e.target.checked;if(saveChats){persist();toast('Chats will be saved on this device.');}else{try{localStorage.removeItem(storageKey);}catch{}toast('Saved copy removed. Chats stay in this tab.');}};$('#clear-chats').onclick=()=>$('#clear-dialog').showModal();$('#confirm-clear').onclick=()=>{if(running)cancelRun();conversations=[];activeChat=null;try{localStorage.removeItem(storageKey);}catch{}renderChats();renderMessages();$('#clear-dialog').close();toast('Conversations cleared.');};

$('#rename-chat-action').onclick=()=>{const c=conversations.find(c=>c.id===chatActionId);if(!c)return;closeChatMenu();$('#rename-chat-input').value=c.title;$('#rename-dialog').showModal();$('#rename-chat-input').focus();$('#rename-chat-input').select();};
$('#rename-chat-form').onsubmit=e=>{e.preventDefault();const title=$('#rename-chat-input').value.trim();if(!title){$('#rename-chat-input').setCustomValidity('Enter a conversation name.');$('#rename-chat-input').reportValidity();return;}const c=conversations.find(c=>c.id===chatActionId);if(c)c.title=title;$('#rename-dialog').close();renderChats();persist();toast('Conversation renamed.');};
$('#rename-chat-input').oninput=e=>e.target.setCustomValidity('');
$('#delete-chat-action').onclick=()=>{const c=conversations.find(c=>c.id===chatActionId);if(!c)return;closeChatMenu();$('#delete-chat-title').textContent=c.title;$('#delete-chat-dialog').showModal();};
$('#confirm-delete-chat').onclick=()=>{if(running?.chat===chatActionId)cancelRun();conversations=conversations.filter(c=>c.id!==chatActionId);if(activeChat===chatActionId){activeChat=null;$('#prompt').value='';syncPlaceholder();renderMessages();}$('#delete-chat-dialog').close();renderChats();persist();toast('Conversation deleted.');};
document.addEventListener('click',e=>{if(!e.target.closest('#chat-menu')&&!e.target.closest('[data-chat-menu]'))closeChatMenu();});
$('#chat-list').addEventListener('scroll',closeChatMenu,{passive:true});
$('#chat-menu').addEventListener('keydown',e=>{if(e.key==='Escape'){const anchor=chatMenuAnchor;closeChatMenu();anchor?.focus();}if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const buttons=[...$('#chat-menu').querySelectorAll('button')];buttons[(buttons.indexOf(document.activeElement)+1)%buttons.length].focus();}});
window.addEventListener('resize',closeChatMenu);

document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#route-drawer').hidden)closeRoute();closeSidebar();}if(e.key==='Tab'&&!$('#route-drawer').hidden){const focusable=[...$('#route-drawer').querySelectorAll('button,a,[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});$('#benchmark-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=benchmarkCategories.indexOf(benchmarkCategory);n=e.key==='Home'?0:e.key==='End'?benchmarkCategories.length-1:(n+(e.key==='ArrowRight'?1:-1)+benchmarkCategories.length)%benchmarkCategories.length;benchmarkCategory=benchmarkCategories[n];benchmarkSubtask='Overview';renderBenchmark();$('#benchmark-tab-'+n).focus();});function placeAdvanced(){const d=$('#advanced-dialog');if(!d.open)return;const anchor=$('#advanced-button').getBoundingClientRect();const width=Math.min(360,innerWidth-32);d.style.width=width+'px';const height=d.offsetHeight;d.style.left=Math.max(16,Math.min(anchor.left,innerWidth-width-16))+'px';d.style.top=Math.max(16,Math.min(anchor.bottom+9+height<=innerHeight-16?anchor.bottom+9:anchor.top-height-9,innerHeight-height-16))+'px';}
function openAdvanced(){$('#advanced-dialog').showModal();$('#advanced-button').setAttribute('aria-expanded','true');placeAdvanced();}
$('#advanced-dialog').addEventListener('close',()=>$('#advanced-button').setAttribute('aria-expanded','false'));
window.addEventListener('resize',placeAdvanced);
